from dataclasses import dataclass
from adaptix import Retort, name_mapping, DebugTrail
from adaptix.load_error import LoadError
@dataclass
class A:
    x: int
    y: int
for d in DebugTrail:
 r=Retort(recipe=[name_mapping(aliases={'x':'old'})],debug_trail=d)
 assert r.load({'old':1,'y':2}, A)==A(1,2)
 for data in ({'old':1},{}, {'x':1,'old':2,'y':3}):
  try:r.load(data,A)
  except LoadError as e: print(d, data, repr(e))
  else: raise AssertionError(data)
print('probes passed')
